import type { SharedRoute, Target } from "../model/route.ts";

/** Generated files, by path relative to the folder they go in. */
export type Files = Map<string, string>;

/**
 * The first line of every generated file: an output starts each file with it, and the writer only
 * replaces or removes a file that has it. A file without it is hand-written, and never touched.
 */
export const GENERATED = "// Generated by mismo from the shared routes folder. Do not edit.\n";

/**
 * Reads a routes folder written in one router's convention, with that router's own parser, and
 * returns the routes one target has. Synchronous: Metro reads its config without waiting.
 */
export interface RouteInput {
  name: string;
  read(source: string, target: Target): SharedRoute[];
  /** A param as this dialect writes it, for the typed routes: `[id]` for Expo Router. */
  param(name: string): string;
}

/**
 * What a router cannot express, checked on the routes its platform has. Every app's build checks
 * the rules of every router the config names (`validFor`), not only its own: a route only one
 * router refuses then fails in every build, before anyone builds that router's app.
 */
export interface RouteRules {
  /** The router, for messages: `TanStack Start`. */
  router: string;
  /** The routes it takes: those its platform has. */
  target: Exclude<Target, "shared">;
  /** What breaks it, one message per route: `(b)/about: …`. None when the routes fit. */
  check(routes: readonly SharedRoute[]): string[];
}

/** What an output writes into. */
export interface OutputContext {
  /** The router's routes folder, absolute. */
  outDir: string;
}

/** Writes one app's routes for its router. Each app's build runs its own. */
export interface RouteOutput {
  name: string;
  /** The routes it takes: those its platform has. */
  target: Exclude<Target, "shared">;
  /** The router's routes folder, relative to the app. */
  outDir: string;
  /** The app's types file, relative to the app: the shared routes plus its platform's own. */
  types: string;
  /** What its router cannot express. */
  rules: RouteRules;
  /**
   * The module that implements `@mismo/core`'s runtime (`Link`, `useNav`, …) on this router, such as
   * `@mismo/tanstack/runtime`. The app's build points `@mismo/core` at it.
   */
  runtime: string;
  emit(routes: SharedRoute[], context: OutputContext): Files;
}

/**
 * A router, as an adapter package exports it: its rules, and what it can do. A config names
 * adapters in `validFor`; an app's build runs one adapter's `output`.
 */
export interface RouterAdapter {
  /** The router, for messages: `TanStack Start`. */
  name: string;
  rules: RouteRules;
  /** Reads routes written in this router's convention. */
  input?(): RouteInput;
  /** Writes an app's routes for this router. */
  output?(options: { outDir: string; types: string }): RouteOutput;
}
